// spec: specs/addbusiness-step5-invoice-name.md (1.1–1.4; подпись поля — #2e5dd0) · кейсы: .qa/tests/addbusiness-step5-invoice-name/ADDBIZ-INV-01.md, -02.md
// seed: tests/seed.user.spec.ts · ПРОД: черновик «QA-TEST …» удаляется в afterEach; запуск только с QA_REAL_WRITE=1.
// «שלח» не нажимается; /api/payments всё равно перехватывается и обрывается.
import { test, expect, Page } from '@playwright/test';
import {
  FREE, PKG2, PKG3, PayCtl, REAL_WRITE, SKIP_REASON, choosePackageAndGoToStep5, deleteDraft,
  expectFieldHidden, expectFieldShown, goToPackageStep, interceptWithPayments, invoiceField, switchPackage,
} from './invoice-name.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });
test.describe.configure({ mode: 'serial' });

async function visibilityByPackage(page: Page, ctl: PayCtl) {
  await goToPackageStep(page, ctl);
  // бесплатный — поля нет (заголовок тикета «כשבוחרים חבילה בתשלום»; комментарий программиста)
  await choosePackageAndGoToStep5(page, FREE);
  await expectFieldHidden(page);
  // платные — поле есть, необязательное («מה רצוי» #8bea2a)
  await switchPackage(page, PKG2);
  await expectFieldShown(page);
  await switchPackage(page, PKG3);
  await expectFieldShown(page);
}

async function valueKeptOnSwitch(page: Page, ctl: PayCtl) {
  const value = 'QA-AUTO חשבונית בע"מ';
  await goToPackageStep(page, ctl);
  await choosePackageAndGoToStep5(page, PKG2);
  await invoiceField(page).fill(value);
  await switchPackage(page, FREE);
  await expectFieldHidden(page);
  await switchPackage(page, PKG2);
  await expect(invoiceField(page), 'значение сохранилось после платный → бесплатный → платный').toHaveValue(value);
}

test.describe('Публикация бизнеса — шаг 5: поле «שם לחשבונית» по пакету', () => {
  let ctl: PayCtl | null = null;

  test.beforeEach(() => test.skip(!REAL_WRITE, SKIP_REASON));
  test.afterEach(async ({ page }) => {
    if (ctl) {
      expect(ctl.payments, 'платёж не запрашивался').toEqual([]);
      await deleteDraft(page, ctl);
    }
    ctl = null;
  });

  test('Поле только при платном пакете: нет у «חבילה 1», есть у «חבילה 2» и «חבילה 3» (подпись «שם לחשבונית» без «מס»/«(לא חובה)», не обязательное, maxlength 100, rtl) #8bea2a #2e5dd0 @desktop @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await visibilityByPackage(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: поле только при платном пакете, подпись «שם לחשבונית» #8bea2a #2e5dd0 @android @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await visibilityByPackage(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Платный → бесплатный → платный: введённое имя сохраняется #8bea2a @desktop @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await valueKeptOnSwitch(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });

  test('Телефон: платный → бесплатный → платный — имя сохраняется #8bea2a @android @data', async ({ page }) => {
    ctl = await interceptWithPayments(page);
    await valueKeptOnSwitch(page, ctl);
    expect(ctl.unexpected, 'кроме своего черновика на прод ничего не записано').toEqual([]);
  });
});
